INSERT INTO public.exercises (slug, name, muscle_group, secondary_muscles, equipment, difficulty, instructions, common_mistakes, alternative_slugs, contraindicated_conditions, is_warmup, met) VALUES
('push-ups','Push Ups','Chest','{"Shoulders","Triceps","Abs"}','{"No Equipment"}','Beginner','1. Start in a high plank, hands slightly wider than shoulders.\n2. Brace your core and squeeze your glutes so your body forms one straight line.\n3. Bend your elbows to about 45 degrees and lower until your chest is a fist''s height from the floor.\n4. Drive the floor away and press back to the top without letting your hips sag.\n5. Breathe in on the way down, out on the way up.','Letting the hips sag or pike up. Flaring the elbows straight out to the sides. Only doing half the range of motion.','{"incline-push-ups","bench-press","dumbbell-floor-press"}','{"Shoulder Injury"}',false,8),
('incline-push-ups','Incline Push Ups','Chest','{"Shoulders","Triceps"}','{"No Equipment","Bench"}','Beginner','1. Place your hands on a bench, step or sturdy chair.\n2. Walk your feet back until your body is one straight line.\n3. Lower your chest towards the surface under control.\n4. Press back up fully.','Hands too far forward. Rushing the reps.','{"push-ups","dumbbell-floor-press"}','{}',false,6),
('bench-press','Bench Press','Chest','{"Shoulders","Triceps"}','{"Full Gym","Basic Gym","Free Weights","Bench"}','Intermediate','1. Lie on the bench with eyes under the bar and feet flat on the floor.\n2. Grip the bar just outside shoulder width and pull your shoulder blades back and down.\n3. Unrack and lower the bar to mid-chest, elbows tucked to about 45 degrees.\n4. Press the bar up and slightly back over your shoulders.\n5. Keep your wrists stacked over your elbows throughout.','Bouncing the bar off the chest. Lifting the hips off the bench. Flaring elbows to 90 degrees.','{"dumbbell-bench-press","push-ups","machine-chest-press"}','{"Shoulder Injury"}',false,6),
('dumbbell-bench-press','Dumbbell Bench Press','Chest','{"Shoulders","Triceps"}','{"Dumbbells","Bench","Free Weights","Full Gym","Basic Gym"}','Beginner','1. Sit on a bench holding a dumbbell in each hand, then lie back bringing them to your shoulders.\n2. Press both dumbbells up until your arms are straight.\n3. Lower slowly until you feel a stretch across the chest.\n4. Keep your wrists neutral and elbows at about 45 degrees.','Clashing the dumbbells at the top. Dropping the weights too fast.','{"bench-press","dumbbell-floor-press","push-ups"}','{"Shoulder Injury"}',false,6),
('dumbbell-floor-press','Dumbbell Floor Press','Chest','{"Triceps"}','{"Dumbbells"}','Beginner','1. Lie on the floor with knees bent, dumbbells at your shoulders.\n2. Press straight up until arms lock out.\n3. Lower until your triceps lightly touch the floor.\n4. Pause, then press again.','Letting the elbows crash into the floor. Arching the lower back.','{"dumbbell-bench-press","push-ups"}','{}',false,5),
('machine-chest-press','Machine Chest Press','Chest','{"Shoulders","Triceps"}','{"Full Gym","Basic Gym","Cable Machine"}','Beginner','1. Set the seat so the handles line up with mid-chest.\n2. Grip the handles and press forward until arms are almost straight.\n3. Return slowly, keeping tension on the chest.','Setting the seat too high. Locking out aggressively.','{"bench-press","push-ups"}','{}',false,5),
('chest-fly','Cable Chest Fly','Chest','{"Shoulders"}','{"Cable Machine","Full Gym"}','Intermediate','1. Set both pulleys at chest height and take a staggered stance.\n2. With a slight elbow bend, bring your hands together in front of your chest.\n3. Squeeze for a second, then open your arms slowly.','Bending the elbows too much and turning it into a press. Using too much weight.','{"dumbbell-bench-press","push-ups"}','{"Shoulder Injury"}',false,5),
('pull-ups','Pull Ups','Back','{"Biceps","Forearms"}','{"Pull-up Bar","Full Gym","Basic Gym"}','Advanced','1. Hang from the bar with an overhand grip just outside shoulder width.\n2. Pull your shoulder blades down, then drive your elbows to your ribs.\n3. Bring your chin above the bar without swinging.\n4. Lower under control to a full hang.','Kipping and swinging. Not reaching a full hang. Shrugging the shoulders up.','{"lat-pulldown","dumbbell-row","resistance-band-row"}','{"Shoulder Injury"}',false,8),
('lat-pulldown','Lat Pulldown','Back','{"Biceps"}','{"Cable Machine","Full Gym","Basic Gym"}','Beginner','1. Sit with thighs secured and grip the bar wider than shoulders.\n2. Lean back slightly and pull the bar to your upper chest.\n3. Squeeze your lats, then let the bar rise slowly.','Using body momentum. Pulling the bar behind the neck.','{"pull-ups","dumbbell-row","resistance-band-row"}','{}',false,5),
('dumbbell-row','Dumbbell Row','Back','{"Biceps","Shoulders"}','{"Dumbbells","Bench","Free Weights","Full Gym","Basic Gym"}','Beginner','1. Place one hand and knee on a bench, other foot on the floor.\n2. Let the dumbbell hang straight down.\n3. Row it towards your hip, leading with the elbow.\n4. Squeeze your back at the top, then lower fully.','Twisting the torso to lift heavier. Yanking with the arm instead of the back.','{"lat-pulldown","resistance-band-row","barbell-row"}','{}',false,6),
('barbell-row','Barbell Row','Back','{"Biceps","Hamstrings"}','{"Free Weights","Full Gym","Basic Gym"}','Intermediate','1. Hinge at the hips until your torso is about 45 degrees, back flat.\n2. Hold the bar with an overhand grip.\n3. Row it to your lower ribs, elbows close to the body.\n4. Lower under control without rounding your back.','Rounding the lower back. Standing too upright.','{"dumbbell-row","lat-pulldown"}','{"Back Pain"}',false,6),
('resistance-band-row','Resistance Band Row','Back','{"Biceps"}','{"Resistance Bands"}','Beginner','1. Anchor the band at chest height and hold one end in each hand.\n2. Step back until there is tension.\n3. Pull your hands to your ribs, squeezing the shoulder blades.\n4. Return slowly.','Shrugging. Letting the band snap back.','{"dumbbell-row","lat-pulldown"}','{}',false,4),
('superman','Superman Hold','Back','{"Glutes"}','{"No Equipment","Yoga Mat"}','Beginner','1. Lie face down with arms extended overhead.\n2. Lift your chest, arms and legs off the floor.\n3. Hold, breathing steadily, then lower slowly.','Straining the neck upward. Holding your breath.','{"resistance-band-row"}','{}',false,3),
('shoulder-press','Shoulder Press','Shoulders','{"Triceps","Abs"}','{"Dumbbells","Free Weights","Full Gym","Basic Gym"}','Intermediate','1. Stand or sit tall with dumbbells at shoulder height, palms forward.\n2. Brace your core and press overhead until arms are straight.\n3. Keep the ribs down — do not arch the lower back.\n4. Lower to ear height under control.','Arching the lower back. Pressing the weights too far in front.','{"arnold-press","pike-push-ups","lateral-raise"}','{"Shoulder Injury","High Blood Pressure"}',false,6),
('arnold-press','Arnold Press','Shoulders','{"Triceps"}','{"Dumbbells"}','Intermediate','1. Start with dumbbells in front of your shoulders, palms facing you.\n2. As you press up, rotate your palms to face forward.\n3. Reverse the rotation on the way down.','Rotating too late. Using momentum from the legs.','{"shoulder-press","lateral-raise"}','{"Shoulder Injury"}',false,6),
('lateral-raise','Lateral Raise','Shoulders','{}','{"Dumbbells","Resistance Bands"}','Beginner','1. Stand with dumbbells at your sides, slight elbow bend.\n2. Raise your arms out to the sides to shoulder height.\n3. Lead with the elbows, not the hands.\n4. Lower slowly.','Swinging the weights. Raising above shoulder height with a shrug.','{"shoulder-press","front-raise"}','{}',false,4),
('front-raise','Front Raise','Shoulders','{}','{"Dumbbells","Resistance Bands"}','Beginner','1. Hold dumbbells in front of your thighs.\n2. Raise one or both arms forward to shoulder height.\n3. Lower under control.','Leaning back. Using momentum.','{"lateral-raise","shoulder-press"}','{}',false,4),
('pike-push-ups','Pike Push Ups','Shoulders','{"Triceps"}','{"No Equipment"}','Intermediate','1. From a downward-dog position, walk your feet in so your hips are high.\n2. Lower the top of your head towards the floor between your hands.\n3. Press back up.','Letting the hips drop into a plank. Flaring elbows wide.','{"shoulder-press","push-ups"}','{"Shoulder Injury","High Blood Pressure"}',false,6),
('face-pull','Face Pull','Shoulders','{"Back"}','{"Cable Machine","Resistance Bands","Full Gym"}','Beginner','1. Set a rope or band at face height.\n2. Pull towards your forehead, splitting your hands apart.\n3. Squeeze your rear delts, then return slowly.','Using too much weight and turning it into a row. Shrugging.','{"resistance-band-row"}','{}',false,4),
('bicep-curls','Bicep Curls','Biceps','{"Forearms"}','{"Dumbbells","Resistance Bands","Free Weights"}','Beginner','1. Stand tall, dumbbells at your sides, palms forward.\n2. Curl the weights up, keeping your elbows pinned to your ribs.\n3. Squeeze at the top, then lower slowly for 2–3 seconds.','Swinging the torso. Letting the elbows drift forward.','{"hammer-curls","resistance-band-curl","chin-ups"}','{}',false,4),
('hammer-curls','Hammer Curls','Biceps','{"Forearms"}','{"Dumbbells"}','Beginner','1. Hold dumbbells with palms facing each other.\n2. Curl up keeping the neutral grip.\n3. Lower with control.','Rushing the lowering phase.','{"bicep-curls","resistance-band-curl"}','{}',false,4),
('resistance-band-curl','Resistance Band Curl','Biceps','{"Forearms"}','{"Resistance Bands"}','Beginner','1. Stand on the band and hold the handles at your sides.\n2. Curl up against the band tension.\n3. Resist on the way down.','Letting the band pull your arms down fast.','{"bicep-curls","hammer-curls"}','{}',false,4),
('chin-ups','Chin Ups','Biceps','{"Back"}','{"Pull-up Bar"}','Advanced','1. Hang from the bar with palms facing you.\n2. Pull your chest to the bar, driving your elbows down.\n3. Lower to a full hang.','Swinging. Half reps.','{"bicep-curls","lat-pulldown"}','{"Shoulder Injury"}',false,8),
('tricep-dips','Tricep Dips','Triceps','{"Chest","Shoulders"}','{"No Equipment","Bench"}','Beginner','1. Sit on the edge of a bench, hands beside your hips.\n2. Slide your hips off the bench, legs extended or bent.\n3. Lower until your elbows reach about 90 degrees.\n4. Press back up through your palms.','Letting the shoulders roll forward. Going too deep and straining the shoulder.','{"tricep-pushdown","overhead-tricep-extension","close-grip-push-ups"}','{"Shoulder Injury"}',false,6),
('tricep-pushdown','Tricep Pushdown','Triceps','{}','{"Cable Machine","Resistance Bands","Full Gym"}','Beginner','1. Grip a rope or bar at chest height.\n2. Keeping elbows at your sides, extend your arms down fully.\n3. Return slowly to the start.','Letting the elbows travel forward. Leaning over the weight.','{"tricep-dips","overhead-tricep-extension"}','{}',false,4),
('overhead-tricep-extension','Overhead Tricep Extension','Triceps','{}','{"Dumbbells"}','Beginner','1. Hold one dumbbell overhead with both hands.\n2. Bend the elbows to lower it behind your head.\n3. Extend back up without flaring the elbows.','Flaring elbows wide. Arching the lower back.','{"tricep-pushdown","tricep-dips"}','{"Shoulder Injury"}',false,4),
('close-grip-push-ups','Close Grip Push Ups','Triceps','{"Chest"}','{"No Equipment"}','Intermediate','1. Set up in a push-up position with hands under your chest, close together.\n2. Lower keeping elbows brushing your ribs.\n3. Press back up.','Letting elbows flare out. Sagging hips.','{"tricep-dips","push-ups"}','{}',false,7),
('wrist-curls','Wrist Curls','Forearms','{}','{"Dumbbells"}','Beginner','1. Rest your forearms on your thighs, palms up, holding light dumbbells.\n2. Curl your wrists up, then lower slowly.','Using too much weight. Moving the elbows.','{"farmers-walk"}','{}',false,3),
('farmers-walk','Farmer''s Walk','Forearms','{"Abs","Shoulders"}','{"Dumbbells","Kettlebell"}','Beginner','1. Hold a heavy weight in each hand at your sides.\n2. Stand tall, shoulders back, core braced.\n3. Walk in a straight line with controlled steps.','Leaning to one side. Shrugging the shoulders.','{"wrist-curls"}','{}',false,5),
('plank','Plank','Abs','{"Shoulders","Glutes"}','{"No Equipment","Yoga Mat"}','Beginner','1. Rest on your forearms and toes, elbows under shoulders.\n2. Squeeze your glutes and brace your abs so your body is one line.\n3. Breathe steadily and hold.','Hips sagging or lifting. Holding your breath.','{"dead-bug","mountain-climbers"}','{}',false,4),
('crunches','Crunches','Abs','{}','{"No Equipment","Yoga Mat"}','Beginner','1. Lie on your back, knees bent, hands by your ears.\n2. Curl your ribs towards your hips, lifting your shoulder blades.\n3. Lower slowly.','Pulling on the neck. Using momentum.','{"dead-bug","leg-raises"}','{"Neck Pain"}',false,4),
('leg-raises','Leg Raises','Abs','{"Quads"}','{"No Equipment","Yoga Mat"}','Intermediate','1. Lie flat, hands under your hips for support.\n2. Keeping legs straight, lift them to 90 degrees.\n3. Lower slowly without letting your back arch.','Arching the lower back. Dropping the legs fast.','{"dead-bug","crunches"}','{"Back Pain"}',false,5),
('dead-bug','Dead Bug','Abs','{}','{"No Equipment","Yoga Mat"}','Beginner','1. Lie on your back, arms up, knees over hips.\n2. Press your lower back into the floor.\n3. Extend one arm and the opposite leg, then return.\n4. Alternate slowly.','Letting the lower back arch. Moving too fast.','{"plank","crunches"}','{}',false,3),
('mountain-climbers','Mountain Climbers','Abs','{"Quads","Shoulders"}','{"No Equipment"}','Beginner','1. Start in a high plank.\n2. Drive one knee towards your chest, then switch.\n3. Keep your hips low and pace steady.','Bouncing the hips. Hands drifting forward.','{"plank","jumping-jacks"}','{"Knee Pain"}',false,8),
('russian-twist','Russian Twist','Abs','{}','{"No Equipment","Kettlebell"}','Intermediate','1. Sit with knees bent, heels lightly on the floor, lean back slightly.\n2. Rotate your torso to tap beside each hip.\n3. Move from the ribs, not just the arms.','Rounding the lower back. Only moving the arms.','{"dead-bug","plank"}','{"Back Pain"}',false,5),
('squats','Bodyweight Squats','Quads','{"Glutes","Hamstrings"}','{"No Equipment"}','Beginner','1. Stand with feet shoulder-width apart, toes slightly out.\n2. Push your hips back and bend your knees.\n3. Lower until thighs are about parallel, chest up.\n4. Drive through your whole foot to stand.','Knees caving inward. Heels lifting. Rounding the back.','{"goblet-squat","leg-press","glute-bridge"}','{}',false,6),
('barbell-squat','Barbell Back Squat','Quads','{"Glutes","Hamstrings","Abs"}','{"Power Rack","Free Weights","Full Gym","Smith Machine"}','Advanced','1. Set the bar on your upper back and unrack it.\n2. Take two steps back, feet shoulder-width.\n3. Brace, sit down and back until thighs are parallel or lower.\n4. Drive up keeping your chest proud.','Letting the chest drop. Knees caving. Rising onto the toes.','{"goblet-squat","leg-press","squats"}','{"Knee Pain","Back Pain","High Blood Pressure"}',false,7),
('goblet-squat','Goblet Squat','Quads','{"Glutes","Abs"}','{"Dumbbells","Kettlebell"}','Beginner','1. Hold a weight at your chest with both hands.\n2. Squat down between your knees, elbows inside your thighs.\n3. Keep your chest tall and drive back up.','Leaning forward. Letting the weight drift away from the body.','{"squats","leg-press","barbell-squat"}','{}',false,6),
('leg-press','Leg Press','Quads','{"Glutes","Hamstrings"}','{"Full Gym","Basic Gym","Cardio Machines"}','Beginner','1. Sit with your back flat on the pad, feet shoulder-width on the platform.\n2. Lower the platform until knees reach about 90 degrees.\n3. Press back without locking out hard.','Letting the hips lift off the seat. Bouncing at the bottom.','{"goblet-squat","squats"}','{}',false,5),
('lunges','Lunges','Quads','{"Glutes","Hamstrings"}','{"No Equipment","Dumbbells"}','Beginner','1. Step forward into a long stride.\n2. Lower until both knees are about 90 degrees.\n3. Push through the front foot to return.\n4. Alternate legs.','Front knee travelling far past the toes. Torso collapsing forward.','{"step-ups","glute-bridge","squats"}','{"Knee Pain"}',false,6),
('step-ups','Step Ups','Quads','{"Glutes"}','{"Bench","Dumbbells"}','Beginner','1. Place one foot fully on a bench or step.\n2. Drive through that leg to stand tall on top.\n3. Lower slowly back down.\n4. Repeat, then switch legs.','Pushing off the back foot. Letting the knee cave in.','{"lunges","squats"}','{}',false,6),
('romanian-deadlift','Romanian Deadlift','Hamstrings','{"Glutes","Back"}','{"Dumbbells","Free Weights","Full Gym"}','Intermediate','1. Hold weights in front of your thighs, knees softly bent.\n2. Push your hips back, sliding the weights down your legs.\n3. Stop when you feel a strong hamstring stretch.\n4. Squeeze your glutes to stand tall.','Rounding the back. Squatting instead of hinging.','{"glute-bridge","hamstring-curl"}','{"Back Pain"}',false,6),
('hamstring-curl','Hamstring Curl','Hamstrings','{}','{"Full Gym","Basic Gym","Resistance Bands"}','Beginner','1. Lie or sit on the machine with the pad above your heels.\n2. Curl your heels towards your glutes.\n3. Lower slowly.','Using momentum. Lifting the hips off the pad.','{"romanian-deadlift","glute-bridge"}','{}',false,4),
('glute-bridge','Glute Bridge','Glutes','{"Hamstrings","Abs"}','{"No Equipment","Yoga Mat"}','Beginner','1. Lie on your back, knees bent, feet flat and close to your hips.\n2. Push through your heels and lift your hips until your body forms a straight line.\n3. Squeeze your glutes hard at the top, then lower slowly.','Arching the lower back instead of squeezing the glutes. Pushing through the toes.','{"hip-thrust","romanian-deadlift","squats"}','{}',false,4),
('hip-thrust','Hip Thrust','Glutes','{"Hamstrings"}','{"Bench","Free Weights","Dumbbells"}','Intermediate','1. Sit with your upper back on a bench and a weight across your hips.\n2. Tuck your chin and drive your hips up until your torso is parallel to the floor.\n3. Squeeze the glutes, then lower under control.','Overextending the lower back. Pushing with the toes only.','{"glute-bridge","romanian-deadlift"}','{}',false,5),
('calf-raises','Calf Raises','Calves','{}','{"No Equipment","Dumbbells"}','Beginner','1. Stand tall, optionally holding weights.\n2. Rise onto the balls of your feet as high as possible.\n3. Pause at the top, then lower slowly below neutral if you have a step.','Bouncing. Cutting the range short.','{"jump-rope"}','{}',false,4),
('jump-rope','Jump Rope','Full Body','{"Calves","Shoulders"}','{"Jump Rope"}','Beginner','1. Hold the handles at hip height, elbows close.\n2. Turn the rope with your wrists, not your arms.\n3. Make small, quiet jumps landing on the balls of your feet.','Jumping too high. Swinging from the shoulders.','{"jumping-jacks","high-knees"}','{"Knee Pain"}',false,10),
('burpees','Burpees','Full Body','{"Chest","Quads","Abs"}','{"No Equipment"}','Advanced','1. From standing, squat down and place your hands on the floor.\n2. Jump or step your feet back to a plank and perform a push-up.\n3. Jump your feet back in.\n4. Explode up into a jump.','Sagging hips in the plank. Landing with stiff knees.','{"mountain-climbers","jumping-jacks","squats"}','{"Knee Pain","Back Pain","High Blood Pressure"}',false,10),
('kettlebell-swing','Kettlebell Swing','Full Body','{"Glutes","Hamstrings","Back"}','{"Kettlebell"}','Intermediate','1. Stand with the kettlebell an arm''s length in front of you.\n2. Hinge at the hips and hike it back between your legs.\n3. Snap your hips forward to float the bell to chest height.\n4. Let it swing back and repeat rhythmically.','Squatting instead of hinging. Lifting with the arms. Overarching at the top.','{"romanian-deadlift","glute-bridge"}','{"Back Pain"}',false,9),
('treadmill-run','Treadmill Run','Full Body','{"Quads","Calves"}','{"Treadmill","Cardio Machines","Full Gym"}','Beginner','1. Start with a 3–5 minute walk to warm up.\n2. Increase to a comfortable running pace you can sustain.\n3. Keep your posture tall and your steps light.\n4. Finish with a slow walk to cool down.','Holding the handrails. Overstriding.','{"exercise-bike-ride","jump-rope"}','{"Knee Pain"}',false,9),
('exercise-bike-ride','Exercise Bike Ride','Full Body','{"Quads","Calves"}','{"Exercise Bike","Cardio Machines","Full Gym"}','Beginner','1. Set the saddle so your knee is slightly bent at the bottom of the pedal stroke.\n2. Warm up easy for 3 minutes.\n3. Ride at a steady effort you can hold, or alternate hard and easy intervals.\n4. Cool down easy for 2 minutes.','Saddle too low. Rocking side to side.','{"treadmill-run","jump-rope"}','{}',false,7),
('jumping-jacks','Jumping Jacks','Full Body','{"Shoulders","Calves"}','{"No Equipment"}','Beginner','1. Stand tall with arms at your sides.\n2. Jump your feet out while sweeping your arms overhead.\n3. Jump back to the start and repeat at a steady rhythm.','Landing flat-footed. Half-raising the arms.','{"high-knees","jump-rope"}','{"Knee Pain"}',true,8),
('high-knees','High Knees','Full Body','{"Abs","Quads"}','{"No Equipment"}','Beginner','1. Jog in place driving each knee to hip height.\n2. Stay light on your feet and pump your arms.','Leaning back. Low knees.','{"jumping-jacks"}','{"Knee Pain"}',true,8),
('arm-circles','Arm Circles','Shoulders','{}','{"No Equipment"}','Beginner','1. Stand with arms out to the sides.\n2. Make small circles forward for 15 seconds, then backward.\n3. Gradually increase the circle size.','Shrugging the shoulders. Going too big too soon.','{}','{}',true,3),
('cat-cow','Cat-Cow Stretch','Back','{"Abs"}','{"No Equipment","Yoga Mat"}','Beginner','1. Start on all fours, wrists under shoulders.\n2. Inhale and drop your belly, lifting your chest and tailbone.\n3. Exhale and round your spine, tucking your chin and tailbone.\n4. Move slowly with your breath.','Rushing. Forcing the range.','{}','{}',true,2),
('hip-circles','Hip Circles','Glutes','{"Quads"}','{"No Equipment"}','Beginner','1. Stand with hands on hips, feet shoulder-width.\n2. Circle your hips slowly one way, then the other.','Moving only the knees.','{}','{}',true,2),
('shoulder-rolls','Shoulder Rolls','Shoulders','{"Back"}','{"No Equipment"}','Beginner','1. Stand tall and roll both shoulders backwards in big slow circles.\n2. Reverse the direction after 15 seconds.','Tensing the neck.','{}','{}',true,2);